-class nsAttachmentState {
- public:
-  nsAttachmentState();
-  nsresult Init(const nsTArray<nsCString>& aContentTypeArray,
-                const nsTArray<nsCString>& aUrlArray,
-                const nsTArray<nsCString>& aDisplayNameArray,
-                const nsTArray<nsCString>& aMessageUriArray);
