-    mListener->OnStartRunningUrl(nullptr);
-  }
-
-  nsresult rv =
-      InternalStartProcessing(aMessenger, aMsgWindow, aAttach, detaching);
-  if (NS_FAILED(rv)) {
-    if (mListener) {
-      mListener->OnStopRunningUrl(nullptr, rv);
-    }
